$groups = Get-LocalGroupMember Administrators
$domain = Get-ADDomain | Select NetBIOSName

$MemberList = $()
$counter = 0

ForEach ($group in $groups) {
	
	$member = ($group.Name).Replace("$($domain.NetBIOSName)\", '')

	$MemberObject = New-Object PSObject

	If ($group.ObjectClass -eq "Group" -And $group.PrincipalSource -eq "ActiveDirectory") {
		
		$members = Get-ADGroupMember -Identity $member -Server irmnet.ds2.dhs.gov 
		$userDetails = $members | Get-ADUser | Select DisplayName,EmailAddress,GivenName,Surname,SamAccountName,UserPrincipalName
		
		$counter++

		$MemberObject | Add-Member -MemberType NoteProperty -Name "DisplayName" -Value $userDetails.DisplayName
		$MemberObject | Add-Member -MemberType NoteProperty -Name "EmailAddress" -Value $userDetails.EmailAddress
		$MemberObject | Add-Member -MemberType NoteProperty -Name "GivenName" -Value $userDetails.GivenName
		$MemberObject | Add-Member -MemberType NoteProperty -Name "Surname" -Value $userDetails.Surname
		$MemberObject | Add-Member -MemberType NoteProperty -Name "SamAccountName" -Value $userDetails.SamAccountName
		$MemberObject | Add-Member -MemberType NoteProperty -Name "UserPrincipalName" -Value $userDetails.UserPrincipalName
		$MemberObject | Add-Member -MemberType NoteProperty -Name "Group" -Value $group
		$MemberList += $MemberObject

	}}
	
	write-host $MemberList
	$GroupMembers | Export-Csv "C:\Temp\groups.csv" -NoTypeInformation -Encoding "UTF8"

	If ($group.ObjectClass -eq "User" -And $group.PrincipalSource -eq "ActiveDirectory") {
		Get-ADUser -Identity $member -server irment.ds2.dhs.gov -Properties DisplayName,EmailAddress,GivenName,Surname,SamAccountName,UserPrincipalName | Export-CSV "C:\Temp\$env:hostname.csv" -Append
	}

}

