function Get-GroupMembers {

    param (
        [string]$GroupName
    )

    Write-Host $GroupName

    $members = Get-ADGroupMember -Identity $GroupName

    Write-Host $members

    $AdminList = foreach ($member in $members) {
        Get-ADUser -Identity $member.SamAccountName -Properties DisplayName,EmailAddress,SamAccountName        
    }

    Write-Host $AdminList

}
